package main
import("encoding/json";"flag";"fmt";"io";"net";"net/http";"os";"path/filepath";"strconv";"strings";"time")
type S struct{Root,Rel string;Port int;Token string}
func readenv(p,k string)string{b,_:=os.ReadFile(p);for _,l:=range strings.Split(string(b),"\n"){x:=strings.SplitN(l,"=",2);if len(x)==2&&x[0]==k{return strings.TrimSpace(x[1])}};return ""}
func (s *S)auth(r *http.Request)bool{return s.Token!=""&&r.Header.Get("X-Hermes-Token")==s.Token}
func js(w http.ResponseWriter,v any){w.Header().Set("Content-Type","application/json");json.NewEncoder(w).Encode(v)}
func readfile(p string)string{b,_:=os.ReadFile(p);return string(b)}
func exists(p string)bool{_,e:=os.Stat(p);return e==nil}
func temp()float64{b,e:=os.ReadFile("/sys/class/power_supply/battery/temp");if e!=nil{return -1};v,_:=strconv.ParseFloat(strings.TrimSpace(string(b)),64);if v>200{v/=10};return v}
func mem()int64{b,_:=os.ReadFile("/proc/meminfo");for _,l:=range strings.Split(string(b),"\n"){if strings.HasPrefix(l,"MemAvailable:"){f:=strings.Fields(l);if len(f)>1{n,_:=strconv.ParseInt(f[1],10,64);return n/1024}}};return -1}
func iface(n string)(string,string){i,e:=net.InterfaceByName(n);if e!=nil{return"DOWN",""};a,_:=i.Addrs();ip:="";for _,x:=range a{if y,ok:=x.(*net.IPNet);ok&&y.IP.To4()!=nil{ip=y.IP.String()}};if ip==""{return"DOWN",""};return"UP",ip}
func (s *S)status(w http.ResponseWriter,r *http.Request){ts,ip:=iface("rndis0");cur:=strings.TrimSpace(readfile(filepath.Join(s.Root,"current_release")));if cur==""{cur="v0.2.0-control-center"};js(w,map[string]any{"service":"HERMES_WORK","control_center":"v0.2.0","release":cur,"temperature_c":temp(),"mem_available_mb":mem(),"tether_state":ts,"tether_ip":ip,"worker_paused":exists(filepath.Join(s.Root,"state","worker_paused")),"safe_mode":exists(filepath.Join(s.Root,"state","safe_mode")),"bridge_enabled":readenv(filepath.Join(s.Rel,"config","work.env"),"BRIDGE_ENABLED")=="1","components":map[string]string{"collector":"NOT_INSTALLED","dedup":"NOT_INSTALLED","categorizer":"NOT_INSTALLED","trend_scoring":"NOT_INSTALLED","reasoning":"NOT_INSTALLED","content_planner":"NOT_INSTALLED","knowledge":"READY_FOUNDATION","scheduler":"READY_FOUNDATION"}})}
func (s *S)action(w http.ResponseWriter,r *http.Request){if !s.auth(r){http.Error(w,"unauthorized",401);return};var q struct{Action string `json:"action"`};json.NewDecoder(r.Body).Decode(&q);st:=filepath.Join(s.Root,"state");switch q.Action{case"pause":os.WriteFile(filepath.Join(st,"worker_paused"),[]byte(time.Now().Format(time.RFC3339)),0600);case"resume":os.Remove(filepath.Join(st,"worker_paused"));os.Remove(filepath.Join(st,"safe_mode"));case"safe_mode":os.WriteFile(filepath.Join(st,"safe_mode"),[]byte("safe_mode"),0600);os.WriteFile(filepath.Join(st,"worker_paused"),[]byte("safe_mode"),0600);case"backup":os.MkdirAll(filepath.Join(s.Root,"backups"),0700);os.WriteFile(filepath.Join(s.Root,"backups","state-"+time.Now().Format("20060102-150405")+".txt"),[]byte("release="+strings.TrimSpace(readfile(filepath.Join(s.Root,"current_release")))+"\n"),0600);case"rollback":p:=strings.TrimSpace(readfile(filepath.Join(s.Root,"previous_release")));if p==""{http.Error(w,"no previous release",409);return};os.WriteFile(filepath.Join(s.Root,"current_release"),[]byte(p+"\n"),0600);default:http.Error(w,"unknown action",400);return};js(w,map[string]any{"ok":true,"action":q.Action})}
func tail(p string,n int)string{b,_:=os.ReadFile(p);a:=strings.Split(string(b),"\n");if len(a)>n{a=a[len(a)-n:]};return strings.Join(a,"\n")}
func (s *S)diag(w http.ResponseWriter,r *http.Request){if !s.auth(r){http.Error(w,"unauthorized",401);return};ts,ip:=iface("rndis0");js(w,map[string]any{"time":time.Now().Format(time.RFC3339),"temp_c":temp(),"mem_mb":mem(),"rndis":ts,"rndis_ip":ip,"release":strings.TrimSpace(readfile(filepath.Join(s.Root,"current_release"))),"bootstrap_log_tail":tail(filepath.Join(s.Root,"logs","hermesd.log"),60),"work_log_tail":tail(filepath.Join(s.Root,"logs","workd.log"),60)})}
func (s *S)update(w http.ResponseWriter,r *http.Request){if !s.auth(r){http.Error(w,"unauthorized",401);return};js(w,map[string]any{"ok":true,"state":"CHANNEL_READY","channel":readenv(filepath.Join(s.Rel,"config","work.env"),"UPDATE_CHANNEL_URL"),"message":"Remote release channel provisioned. Downloader activation is next signed runtime step."})}
func (s *S)index(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","text/html; charset=utf-8");io.WriteString(w,page)}
func main(){root:=flag.String("root","/data/adb/hermes_work","");rel:=flag.String("release","","");flag.Parse();p:=8766;if x:=readenv(filepath.Join(*rel,"config","work.env"),"WORK_PORT");x!=""{p,_=strconv.Atoi(x)};s:=&S{Root:*root,Rel:*rel,Port:p,Token:readenv(filepath.Join(*root,"config.env"),"ADMIN_TOKEN")};m:=http.NewServeMux();m.HandleFunc("/",s.index);m.HandleFunc("/api/work/status",s.status);m.HandleFunc("/api/work/action",s.action);m.HandleFunc("/api/work/diagnostics",s.diag);m.HandleFunc("/api/work/update",s.update);http.ListenAndServe(fmt.Sprintf("0.0.0.0:%d",p),m)}
const page=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HERMES WORK</title><style>body{margin:0;background:#0d1117;color:#e6edf3;font:14px system-ui}main{max-width:1050px;margin:auto;padding:18px}.card{padding:16px;margin:12px 0;border:1px solid #30363d;background:#161b22;border-radius:14px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.box{background:#0d1117;border:1px solid #30363d;border-radius:11px;padding:12px}.k{font-size:11px;color:#8b949e}.v{font-size:18px;font-weight:700}.ok{color:#3fb950}.warn{color:#d29922}button,input{background:#21262d;color:#e6edf3;border:1px solid #30363d;border-radius:9px;padding:10px;margin:4px}.primary{background:#238636}pre{white-space:pre-wrap;background:#010409;padding:12px;border-radius:10px}</style></head><body><main><h2>HERMES WORK <span id="online">CONNECTING</span></h2><p>Digital Work Control Center · Redmi 5A</p><div class="card"><div class="grid"><div class="box"><div class="k">MODEM</div><div id="tether" class="v">-</div></div><div class="box"><div class="k">TEMP</div><div id="temp" class="v">-</div></div><div class="box"><div class="k">FREE RAM</div><div id="ram" class="v">-</div></div><div class="box"><div class="k">WORKER</div><div id="worker" class="v">-</div></div><div class="box"><div class="k">RELEASE</div><div id="release" class="v">-</div></div></div></div><div class="card"><h3>Work Pipeline</h3><p>Research → Dedup → Categorize → Trend Score → Content Brief → Production → Feedback</p><div id="components" class="grid"></div></div><div class="card"><h3>Update & Recovery</h3><input id="token" type="password" placeholder="Admin token"><button class="primary" id="update">CHECK / UPDATE NOW</button><button id="backup">BACKUP</button><button id="safe">SAFE MODE</button><button id="resume">RESUME</button><button id="rollback">ROLLBACK</button><button id="diag">DIAGNOSTICS</button><pre id="out">Ready.</pre></div><div class="card"><h3>ChatGPT / HERMES Bridge</h3><p>Bridge foundation ready. Root terminal remains LAN-only.</p></div></main><script>const $=x=>document.getElementById(x);function h(){return {'X-Hermes-Token':$('token').value.trim(),'Content-Type':'application/json'}}async function st(){try{let j=await(await fetch('/api/work/status')).json();$('online').textContent='● ONLINE';$('tether').textContent=j.tether_state+' '+j.tether_ip;$('temp').textContent=j.temperature_c.toFixed(1)+' °C';$('ram').textContent=j.mem_available_mb+' MB';$('worker').textContent=j.safe_mode?'SAFE MODE':(j.worker_paused?'PAUSED':'READY');$('release').textContent=j.release;$('components').innerHTML=Object.entries(j.components).map(([k,v])=>'<div class="box"><div class="k">'+k.toUpperCase()+'</div><div class="v '+(v.includes('NOT')?'warn':'')+'">'+v+'</div></div>').join('')}catch(e){$('online').textContent='● OFFLINE'}}async function act(a){let r=await fetch('/api/work/action',{method:'POST',headers:h(),body:JSON.stringify({action:a})});$('out').textContent=await r.text();st()}$('backup').onclick=()=>act('backup');$('safe').onclick=()=>act('safe_mode');$('resume').onclick=()=>act('resume');$('rollback').onclick=()=>act('rollback');$('diag').onclick=async()=>{$('out').textContent=await(await fetch('/api/work/diagnostics',{headers:h()})).text()};$('update').onclick=async()=>{$('out').textContent=await(await fetch('/api/work/update',{method:'POST',headers:h()})).text()};st();setInterval(st,5000)</script></body></html>`